<script setup lang="ts">
const config = useRuntimeConfig(); const form = reactive({ name:'', email:'', password:'', password_confirmation:'' }); const message=ref(''); const errorMessage=ref('')
const submit = async () => { message.value=''; errorMessage.value=''; try { await $fetch(`${config.public.apiBase}/auth/register`, {method:'POST', body:form}); message.value='Account created. Check your email for the verification link.' } catch { errorMessage.value='Registration failed. Check the entered data.' } }
</script>
<template><div class="min-h-screen bg-base-100"><AppHeader/><main class="mx-auto grid min-h-[calc(100vh-4rem)] max-w-md place-items-center px-4 py-10"><div class="card w-full border border-base-content/10"><div class="card-body gap-4"><h1 class="card-title text-2xl">{{ $t('auth.create') }}</h1><input v-model="form.name" class="input" placeholder="Name"><input v-model="form.email" class="input" type="email" placeholder="Email"><input v-model="form.password" class="input" type="password" placeholder="Password"><input v-model="form.password_confirmation" class="input" type="password" placeholder="Confirm password"><div v-if="message" class="alert alert-success alert-soft text-sm">{{ message }}</div><div v-if="errorMessage" class="alert alert-error alert-soft text-sm">{{ errorMessage }}</div><button class="btn btn-primary" @click="submit">{{ $t('auth.create') }}</button></div></div></main></div></template>
